entry.css:
html,body{height:100%}
#wrap{display:flex;flex-direction:column;height:100%;padding:9px 9px 0;gap:7px;overflow:hidden}

#top{display:flex;align-items:center;gap:6px;flex-shrink:0}
.seg{display:flex;flex:1;background:var(--nuo-surface);border-radius:9px;padding:2px;gap:2px}
.sg{flex:1;border:0;background:transparent;color:var(--nuo-fg-dim);font-size:12px;line-height:1;
    padding:7px 4px;border-radius:7px;cursor:pointer;transition:.15s;font-family:inherit}
.sg.on{background:var(--nuo-bg);color:var(--nuo-fg);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.14)}
.sg:active{transform:scale(.97)}
.ico{border:0;background:var(--nuo-surface);color:var(--nuo-fg-dim);width:30px;height:30px;
     border-radius:9px;font-size:15px;line-height:1;cursor:pointer;flex-shrink:0;font-family:inherit}
.ico:active{transform:rotate(90deg);transition:.2s}

#who{flex-shrink:0;font-size:11px;line-height:1.3;color:var(--nuo-fg-dim);
     white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding:0 2px}

.rowsw{flex-shrink:0;display:flex;align-items:center;gap:9px;background:var(--nuo-surface);
       border-radius:10px;padding:8px 10px}
.rl{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.rl b{font-size:12.5px;font-weight:600;line-height:1.25}
.rl span{font-size:10.5px;line-height:1.3;color:var(--nuo-fg-dim)}

#search{flex-shrink:0;display:flex;align-items:center;gap:6px;background:var(--nuo-surface);
        border:1px solid var(--nuo-border);border-radius:9px;padding:0 9px}
#search span{font-size:11px;opacity:.55}
#q{flex:1;min-width:0;border:0;background:transparent;color:var(--nuo-fg);
   padding:7px 0;font-size:12px;outline:none;font-family:inherit}

#list{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column;
      gap:5px;min-height:50px;padding-bottom:2px}
#list::-webkit-scrollbar{width:4px}
#list::-webkit-scrollbar-thumb{background:var(--nuo-border);border-radius:4px}
#list.off .sw{opacity:.45}

.bk{background:var(--nuo-surface);border-radius:10px;overflow:hidden;flex-shrink:0}
.bkr{display:flex;align-items:center;gap:6px;padding:8px 9px}
.arw{border:0;background:transparent;color:var(--nuo-fg-dim);cursor:pointer;font-size:9px;
     line-height:1;width:18px;height:24px;padding:0;flex-shrink:0;transition:.15s;font-family:inherit}
.arw.op{transform:rotate(90deg)}
.arw.no{opacity:0;pointer-events:none}
.bkn{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.bkt{font-size:12.5px;font-weight:500;line-height:1.3;display:flex;align-items:center;gap:4px;min-width:0}
.bkt em{font-style:normal;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bks{font-size:10px;line-height:1.35;color:var(--nuo-fg-dim)}
.tag{font-size:9px;line-height:1.5;border:1px solid var(--nuo-border);border-radius:4px;
     padding:0 3px;color:var(--nuo-fg-dim);flex-shrink:0}
.tag.g{color:#c9a227;border-color:rgba(201,162,39,.45)}

.ents{padding:0 10px 8px 27px;display:flex;flex-direction:column}
.all{display:flex;gap:6px;padding:2px 0 4px}
.all button{flex:1;border:1px solid var(--nuo-border);background:transparent;color:var(--nuo-fg-dim);
            font-size:10.5px;line-height:1;border-radius:7px;padding:5px 0;cursor:pointer;font-family:inherit}
.all button:active{background:var(--nuo-border)}
.ent{display:flex;align-items:center;gap:7px;padding:6px 0;border-top:1px solid var(--nuo-border)}
.entn{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.entn b{font-size:11.5px;font-weight:400;line-height:1.3;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.entn i{font-style:normal;font-size:9.5px;line-height:1.3;color:var(--nuo-fg-dim);
        white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

.sw{position:relative;display:inline-block;width:32px;height:19px;flex-shrink:0}
.sw.sm{width:28px;height:17px}
.sw input{opacity:0;width:0;height:0;position:absolute}
.sw i{position:absolute;inset:0;background:var(--nuo-border);border-radius:20px;transition:.18s}
.sw i:after{content:"";position:absolute;width:15px;height:15px;left:2px;top:2px;background:#fff;
            border-radius:50%;transition:.18s;box-shadow:0 1px 2px rgba(0,0,0,.25)}
.sw.sm i:after{width:13px;height:13px}
.sw input:checked + i{background:var(--nuo-ok)}
.sw input:checked + i:after{transform:translateX(13px)}
.sw.sm input:checked + i:after{transform:translateX(11px)}
.sw input:disabled + i{opacity:.4}

#msg{font-size:11.5px;line-height:1.5;color:var(--nuo-fg-dim);text-align:center;padding:24px 12px}
#foot{flex-shrink:0;font-size:10px;line-height:1.3;color:var(--nuo-fg-dim);text-align:center;
      padding:6px 0 7px;border-top:1px solid var(--nuo-border);margin-top:1px}
.hide{display:none!important}

entry.js:
// 世界书开关：只改「这个聊天吃哪些书 / 关掉哪些词条」，世界书内容一个字都不碰。
// 语义与聊天设定里那个面板完全一致（读写的就是同一份 chatSettings.wbConfig）。
var $ = function (id) { return document.getElementById(id); };
var state = null;      // 宿主回来的快照
var scope = 'online';  // online | offline
var charId = null;
var charName = '';
var open = {};         // bookId -> 是否展开
var busy = false;

// 面板挂在「此时此刻」里 → 默认就看线下那一份，省一次点击
if (document.body.getAttribute('data-slot') === 'appPanel') scope = 'offline';

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

function paintScope() {
  var bs = document.querySelectorAll('#scope .sg');
  for (var i = 0; i < bs.length; i++) {
    bs[i].className = 'sg' + (bs[i].getAttribute('data-scope') === scope ? ' on' : '');
  }
  $('sep').className = 'rowsw' + (scope === 'offline' ? '' : ' hide');
}

// 空名字就整行不显示 —— 之前会孤零零留一个「· 线上」在那里
function paintWho() {
  var txt = charName ? ('当前：' + charName) : '';
  $('who').textContent = txt;
  $('who').className = txt ? '' : 'hide';
}

function show(text) {
  $('msg').textContent = text;
  $('msg').className = text ? '' : 'hide';
  $('list').innerHTML = '';
  $('foot').textContent = '';
}

function load() {
  paintScope();
  return nuo.context().then(function (c) {
    charId = c && c.charId ? String(c.charId) : null;
    charName = (c && c.charName) || '';
    paintWho();
    if (!charId) { state = null; show('先打开一个聊天，再来开关世界书'); return; }
    return nuo.worldbook.config({ charId: charId, scope: scope }).then(function (s) {
      state = s;
      render();
    });
  }).catch(function (e) { show('读取失败：' + (e && e.message || e)); });
}

// 写回：整份 enabledBooks / disabledEntries 一起送
function persist(patch) {
  if (!state || !charId || busy) return Promise.resolve();
  busy = true;
  var body = {
    charId: charId, scope: scope,
    custom: patch.custom === undefined ? state.custom : patch.custom,
    enabledBooks: patch.enabledBooks || state.enabledBooks,
    disabledEntries: patch.disabledEntries || state.disabledEntries
  };
  if (patch.separate !== undefined) body.separate = patch.separate;
  return nuo.worldbook.set(body).then(function () {
    busy = false;
    // 切换「与线上分开」会换掉整份数据源，必须重读而不是就地改
    if (patch.separate !== undefined) return load();
    state.custom = body.custom;
    state.enabledBooks = body.enabledBooks;
    state.disabledEntries = body.disabledEntries;
    render();
  }).catch(function (e) { busy = false; show('保存失败：' + (e && e.message || e)); });
}

function has(arr, v) { return arr.indexOf(String(v)) >= 0; }
function without(arr, v) { return arr.filter(function (x) { return String(x) !== String(v); }); }
function withv(arr, v) { return has(arr, v) ? arr.slice() : arr.concat([String(v)]); }

function render() {
  if (!state) return;
  $('msg').className = 'hide';
  $('custChk').checked = !!state.custom;
  $('sepChk').checked = !!state.separate;
  $('custHint').textContent = state.custom
    ? '勾选的书才生效，词条可单独关'
    : '跟着名册／全局走，要改先打开';
  $('list').className = state.custom ? '' : 'off';

  var q = $('q').value.trim().toLowerCase();
  var html = '';
  var shown = 0, onBooks = 0, onEnts = 0;

  for (var i = 0; i < state.books.length; i++) {
    var b = state.books[i];
    var ents = b.entries || [];
    var on = has(state.enabledBooks, b.id);
    var live = ents.filter(function (e) { return !e.uid || !has(state.disabledEntries, e.uid); });
    if (on) { onBooks++; onEnts += live.length; }

    var hitBook = !q || (b.name || '').toLowerCase().indexOf(q) >= 0;
    var hitEnts = ents.filter(function (e) {
      return !q || hitBook || (e.name || '').toLowerCase().indexOf(q) >= 0
        || (e.keys || '').toLowerCase().indexOf(q) >= 0;
    });
    if (!hitBook && !hitEnts.length) continue;
    shown++;

    var expanded = !!open[b.id] || (!!q && !hitBook);
    html += '<div class="bk"><div class="bkr">'
      + '<button class="arw' + (ents.length ? (expanded ? ' op' : '') : ' no')
      + '" data-arw="' + esc(b.id) + '">&#9654;</button>'
      + '<div class="bkn"><div class="bkt"><em>' + esc(b.name || '未命名') + '</em>'
      + (b.isGlobal ? '<span class="tag g">全局</span>' : '')
      + (b.fromRoster ? '<span class="tag">名册</span>' : '')
      + '</div><div class="bks">'
      + (ents.length ? (on ? (live.length + ' / ' + ents.length + ' 条生效') : (ents.length + ' 条词条')) : '空书')
      + '</div></div>'
      + '<label class="sw"><input type="checkbox" data-book="' + esc(b.id) + '"'
      + (on ? ' checked' : '') + (state.custom ? '' : ' disabled') + '><i></i></label>'
      + '</div>';

    if (expanded && ents.length) {
      var list = (q && !hitBook) ? hitEnts : ents;
      html += '<div class="ents"><div class="all">'
        + '<button data-all="on" data-bid="' + esc(b.id) + '">全开</button>'
        + '<button data-all="off" data-bid="' + esc(b.id) + '">全关</button></div>';
      for (var j = 0; j < list.length; j++) {
        var e = list[j];
        var eon = e.uid ? !has(state.disabledEntries, e.uid) : true;
        html += '<div class="ent"><span class="entn"><b>' + esc(e.name || ('#' + (j + 1)))
          + (e.constant ? ' <span class="tag">常驻</span>' : '') + '</b>'
          + (e.keys ? '<i>' + esc(e.keys) + '</i>' : '') + '</span>'
          + '<label class="sw sm"><input type="checkbox" data-ent="' + esc(e.uid) + '"'
          + ((eon && on) ? ' checked' : '')
          + ((!e.uid || !on || !state.custom) ? ' disabled' : '') + '><i></i></label></div>';
      }
      html += '</div>';
    }
    html += '</div>';
  }

  $('list').innerHTML = shown ? html
    : '<div style="font-size:11.5px;opacity:.6;text-align:center;padding:24px 12px">'
      + (q ? '没有匹配的世界书' : '还没有世界书') + '</div>';
  $('foot').textContent = state.books.length
    ? ('本聊天生效：' + onBooks + ' 本书 · ' + onEnts + ' 条词条')
    : '';
}

// 事件委托：列表整块重绘，逐个绑定会随重绘一起失效
$('list').addEventListener('click', function (ev) {
  var t = ev.target;
  var arw = t.getAttribute && t.getAttribute('data-arw');
  if (arw) { open[arw] = !open[arw]; render(); return; }
  var all = t.getAttribute && t.getAttribute('data-all');
  if (all && state && state.custom) {
    var bid = t.getAttribute('data-bid');
    var bk = state.books.filter(function (b) { return b.id === bid; })[0];
    if (!bk) return;
    var dis = state.disabledEntries.slice();
    (bk.entries || []).forEach(function (e) {
      if (!e.uid) return;
      dis = all === 'on' ? without(dis, e.uid) : withv(dis, e.uid);
    });
    persist({ disabledEntries: dis });
  }
});

$('list').addEventListener('change', function (ev) {
  var t = ev.target;
  if (!state || !state.custom) return;
  var bid = t.getAttribute('data-book');
  if (bid) {
    persist({ enabledBooks: t.checked ? withv(state.enabledBooks, bid) : without(state.enabledBooks, bid) });
    return;
  }
  var uid = t.getAttribute('data-ent');
  if (uid) {
    // 禁用集：关掉才进集合，打开就是从集合里拿掉
    persist({ disabledEntries: t.checked ? without(state.disabledEntries, uid) : withv(state.disabledEntries, uid) });
  }
});

$('custChk').addEventListener('change', function () {
  if (!state) return;
  // 从关到开：以当前继承集合为起点，否则一开就变成「一本书都没勾」
  var next = (this.checked && (!state.enabledBooks || !state.enabledBooks.length))
    ? (state.inherited || []) : state.enabledBooks;
  persist({ custom: this.checked, enabledBooks: next });
});

$('sepChk').addEventListener('change', function () { persist({ separate: this.checked }); });
$('q').addEventListener('input', function () { render(); });
$('refresh').addEventListener('click', function () { load(); });

var sgs = document.querySelectorAll('#scope .sg');
for (var k = 0; k < sgs.length; k++) {
  sgs[k].addEventListener('click', function () {
    scope = this.getAttribute('data-scope');
    try { nuo.storage.set('scope', scope); } catch (e) {}
    load();
  });
}

// 换聊天了就重读 —— 悬浮窗是常驻的，不重读会对着上一个角色开关
nuo.on('chatOpen', function () { load(); });

nuo.storage.get('scope').then(function (v) {
  if (v === 'online' || v === 'offline') scope = v;
}).catch(function () {}).then(function () {
  nuo.ready();
  load();
});
